mapper.select:
SELECT s.fqn AS "fqn", f.path AS "path", f.file_id AS "fileId"
  FROM analysis_symbol s
  JOIN analysis_file f ON f.file_id = s.file_id
 WHERE s.revision_id = #{revisionId}
   AND s.file_id <> #{fileId}
   AND s.symbol_id IN
#{symbolId}
 ORDER BY s.outer_symbol_id NULLS FIRST, s.fqn
 LIMIT 5

mapper.update:
UPDATE analysis_file
   SET parse_status = #{parseStatus}
     , parse_error = #{parseError}

     , language_level = #{languageLevel}


     , package_name = #{packageName}
     , source_root = #{sourceRoot}

 WHERE file_id = #{fileId}

